using System;
using System.Diagnostics;
using System.IO;
using System.Text;
using System.Windows.Forms;
using Microsoft.Win32;

namespace LovelyKidsPrintBridgeSetup
{
    internal static class Program
    {
        private const string AppName =
            "Lovely Kids Print Bridge";

        private const string PayloadBase64 =
            "";

        [STAThread]
        private static void Main()
        {
            try
            {
                string installDir = Path.Combine(
                    Environment.GetFolderPath(
                        Environment.SpecialFolder.LocalApplicationData),
                    "LovelyKids",
                    "PrintBridge"
                );

                string exePath = Path.Combine(
                    installDir,
                    "LovelyKidsPrintBridge.exe"
                );

                Directory.CreateDirectory(installDir);

                // Stop previous standalone/installed copies.
                string[] processNames = {
                    "LovelyKidsPrintBridgeStandalone",
                    "LovelyKidsPrintBridge"
                };

                foreach (string name in processNames)
                {
                    foreach (Process p in Process.GetProcessesByName(name))
                    {
                        try
                        {
                            if (p.Id != Process.GetCurrentProcess().Id)
                            {
                                p.Kill();
                                p.WaitForExit(3000);
                            }
                        }
                        catch { }
                    }
                }

                byte[] appBytes =
                    Convert.FromBase64String(PayloadBase64);

                File.WriteAllBytes(exePath, appBytes);

                // Windows auto-start for current user.
                using (RegistryKey runKey =
                    Registry.CurrentUser.CreateSubKey(
                        @"Software\Microsoft\Windows\CurrentVersion\Run"))
                {
                    runKey.SetValue(
                        "Lovely Kids Print Bridge",
                        "\"" + exePath + "\"",
                        RegistryValueKind.String
                    );
                }

                // Remove old Startup shortcut if it exists.
                string startup =
                    Environment.GetFolderPath(
                        Environment.SpecialFolder.Startup);

                string oldShortcut =
                    Path.Combine(
                        startup,
                        "Lovely Kids Print Bridge.lnk"
                    );

                try
                {
                    if (File.Exists(oldShortcut))
                        File.Delete(oldShortcut);
                }
                catch { }

                ProcessStartInfo start =
                    new ProcessStartInfo();

                start.FileName = exePath;
                start.WorkingDirectory = installDir;
                start.UseShellExecute = true;

                Process.Start(start);

                MessageBox.Show(
                    "Lovely Kids Print Bridge was installed successfully.\r\n\r\n" +
                    "The program will now run automatically with Windows.\r\n" +
                    "If needed, choose the label printer from the program settings.",
                    AppName,
                    MessageBoxButtons.OK,
                    MessageBoxIcon.Information
                );
            }
            catch (Exception ex)
            {
                MessageBox.Show(
                    "Installation failed:\r\n\r\n" + ex.Message,
                    AppName,
                    MessageBoxButtons.OK,
                    MessageBoxIcon.Error
                );
            }
        }
    }
}
